@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ex: <http://example.org/> .

ex:PersonShape a sh:NodeShape
  sh:targetClass ex:Person

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ex: <http://example.org/> .

ex:PersonShape a sh:NodeShape ;
  sh:property [
    sh:path ex:name ;
    sh:minCount "not-a-number"
  ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ex: <http://example.org/> .

ex:PersonShape a sh:NodeShape ;
  sh:property [
    sh:path ex:name ;
    sh:nodeKind ex:InvalidNodeKind
  ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ex: <http://example.org/> .

ex:PersonShape a sh:NodeShape ;
  sh:property [
    sh:path ex:email ;
    sh:pattern "[invalid-regex("
  ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ex: <http://example.org/> .

ex:PersonShape a sh:NodeShape ;
  sh:property [
    sh:path ex:name ;
    sh:minCount 1
  ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ex: <http://example.org/> .

ex:ShapeA a sh:NodeShape ;
  sh:property [
    sh:path ex:relatedTo ;
    sh:node ex:ShapeB
  ] .

ex:ShapeB a sh:NodeShape ;
  sh:property [
    sh:path ex:relatedTo ;
    sh:node ex:ShapeA
  ] .
